import sys

def main():
    s, k = sys.stdin.read().split()[:2]
    k = int(k)
    cnt = {}
    l = 0
    best = 0
    for r, ch in enumerate(s):
        cnt[ch] = cnt.get(ch, 0) + 1
        while len(cnt) > k:
            c = s[l]
            cnt[c] -= 1
            if cnt[c] == 0:
                del cnt[c]
            l += 1
        if r - l + 1 > best:
            best = r - l + 1
    print(best)

